        "passage": "“Tiền giấy chẳng qua chỉ là mảnh giấy vuông, phí tổn chỉ đáng năm ba đồng tiền, mà đem đổi lấy vật đáng 5 - 6 trăm đồng của người ta, cố nhiên không phải là cái đạo đúng mức. Vả lại, người có tiền giấy cất giữ cũng dễ rách nát, mà kẻ làm giả mạo sinh ra không cùng, thực không phải là cách bình ổn vật giá mà lưu thông của cải của dân vậy. Quý Ly không xem xét kĩ đến cái gốc lợi hại, chỉ ham chuộng hư danh sáng chế, để cho tiền của hàng hoá thường vẫn lưu thông tức là sinh ra ứ đọng, khiến dân nghe thấy đã sợ, thêm mối xôn xao, thể có phải là chế độ bình trị đâu”. (Phan Huy Chú, Lịch triều hiến chương loại chí, tập 2, NXB Giáo dục, Hà Nội, 2006, tr.112)",
