        "passage": "“Nay quan gia còn trẻ thơ mà thiên tai xảy ra luôn, trẫm (tức Lê Nhân Tông) rất lo sợ. Mối hại ngày nay có thể là do gây bè cánh, tiến cử không công bằng, có thể vì cậy thế công thần nơi tiềm để cho vợ con chạy chọt nhờ vả nơi quyền thế, có thể do để bọn gia nô làm hại dân lành, hay thậm thụt ở các nhà quyền thế để xin khỏi tội,..” (Ngô Sĩ Liên và các sử thần triều Hậu Lê, Đại Việt sử kí toàn thư, Tập 2, NXB Khoa học xã hội, Hà Nội, 1998, tr.372)",
