        "passage": "“Nội các là một cơ yếu, phải đặc cách chọn lấy những bề tôi chầu hầu tùy tùng ở bên nhà vua khiến cho ra vào gần gụi đề phòng khi cần hỏi han. Những người sung vào chức đó thì lấy ở hàng quan Tam, Tứ phẩm trong các bộ, các viện, còn các thuộc viên thì lấy những người có chức hàm trong Viện hàn lâm sung vào, các bậc thì ở dưới Lục bộ. Phàm những sắc, chiếu, sớ tấu, sách vở, ghi chép, hoặc xem xét giấy tờ, đều thuộc tòa Nội các cả; những viên chức đó đều tùy theo công việc nặng nhẹ, nhiều ít, chước lượng mà chia ra từng tào để cho có chuyên trách”. (Lời dụ của Minh Mạng, trích trong: Quốc sử quán triều Nguyễn, Đại Nam thực lục, Tập 3, NXB Giáo dục, Hà Nội, 2004)",
