        "passage": "Biển Đông có nguồn tài nguyên sinh vật phong phú và đa dạng, có đến hơn 160 000 loài, gần 10 000 loài thực vật và 260 loài chim sống ở biển. Trong đó, trữ lượng cá ở vùng biển nước ta khoảng 5 triệu tấn/năm, trữ lượng cá có thể đánh bắt hàng năm khoảng 2,3 triệu tấn. Trữ lượng dầu mỏ và khí đốt ở thềm lục địa Việt Nam được xác minh là gần 550 triệu tấn dầu và trên 610 tỉ m3 khí…. Bờ biển Việt Nam dài và có nhiều bãi cát, vịnh, hang động tự nhiên đẹp như Hạ Long, Hải Phòng, Đà Nẵng, Quy Nhơn, Nha Trang, Vũng Tàu, Hà Tiên,… là tiềm năng cho phát triển kinh tế du lịch. Đặc biệt, hệ thống ven biển của Việt Nam có nhiều địa điểm thuận lợi cho việc xây dựng các cảng nước sâu và trung bình, phục vụ tốt cho sự phát triển kinh tế đất nước. (Sách giáo khoa Lịch sử 11, Bộ chân trời sáng tạo, tr.85)",
